    correction: [{"quoi":"نحسب الفرق","math":"<span dir=\"ltr\" class=\"expr\">(-a - <span class=\"frac\"><span class=\"num\">17</span><span class=\"den\">7</span></span>) - (-b + <span class=\"frac\"><span class=\"num\">12</span><span class=\"den\">7</span></span>) = (b - a) - <span class=\"frac\"><span class=\"num\">29</span><span class=\"den\">7</span></span></span>"},{"quoi":"نعوّض بالمعطى","math":"<span dir=\"ltr\" class=\"expr\">(b - a) - <span class=\"frac\"><span class=\"num\">29</span><span class=\"den\">7</span></span> = (-<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">14</span></span>) - <span class=\"frac\"><span class=\"num\">29</span><span class=\"den\">7</span></span></span>"},{"quoi":"نحسب","math":"<span dir=\"ltr\" class=\"expr\">(-<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">14</span></span>) - <span class=\"frac\"><span class=\"num\">29</span><span class=\"den\">7</span></span> = -<span class=\"frac\"><span class=\"num\">59</span><span class=\"den\">14</span></span></span>"},{"quoi":"نحدّد إشارة الفرق","math":"<span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">59</span><span class=\"den\">14</span></span> &lt; 0</span>"},{"quoi":"القاعدة","math":"الفرق سالب، إذن العبارة الأولى أصغر"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">-a - <span class=\"frac\"><span class=\"num\">17</span><span class=\"den\">7</span></span> &lt; -b + <span class=\"frac\"><span class=\"num\">12</span><span class=\"den\">7</span></span></span>"}],
