    correction: [{"quoi":"نرفع القوس المسبوق بعلامة الطرح","math":"<span dir=\"ltr\" class=\"expr\">- (-c + b - a + <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span>) = c - b + a - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span></span>"},{"quoi":"تنبيه","math":"علامة الطرح أمام قوس تنقلب على كلّ حدوده، لا على الأوّل فقط"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">A = -a - b + c + <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> + c - b + a - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span></span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">A = (-a + a) + (c + c) + (-b - b) + (<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span>)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> = <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">6</span></span></span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">A = 2c - 2b + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">6</span></span></span>"}],
