    correction: [{"quoi":"نرفع القوسين","math":"<span dir=\"ltr\" class=\"expr\">(a - c) - (a - b) = a - c - a + b</span>"},{"quoi":"تنبيه","math":"علامة الطرح أمام قوس تنقلب على كلّ حدوده، لا على الأوّل فقط"},{"quoi":"يختفي a","math":"<span dir=\"ltr\" class=\"expr\">a - c - a + b = b - c</span>"},{"quoi":"نعبّر بالمعطيين","math":"<span dir=\"ltr\" class=\"expr\">b - c = -(c - a) - (a - b)</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">b - c = -<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> - (-<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span>)</span>"},{"quoi":"نحسب","math":"<span dir=\"ltr\" class=\"expr\">b - c = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span></span>"},{"quoi":"نحدّد إشارة الفرق","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span> &gt; 0</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">b &gt; c</span>"}],
