    correction: [{"quoi":"نرفع القوس الأول","math":"<span dir=\"ltr\" class=\"expr\">- (x + <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">8</span></span>) = -x - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">8</span></span></span>"},{"quoi":"تنبيه","math":"علامة الطرح أمام قوس تنقلب على كلّ حدوده، لا على الأوّل فقط"},{"quoi":"نرفع القوس الثاني","math":"<span dir=\"ltr\" class=\"expr\">- (<span class=\"frac\"><span class=\"num\">14</span><span class=\"den\">3</span></span> - y) = -<span class=\"frac\"><span class=\"num\">14</span><span class=\"den\">3</span></span> + y</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">E = <span class=\"frac\"><span class=\"num\">14</span><span class=\"den\">3</span></span> - x - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">8</span></span> - <span class=\"frac\"><span class=\"num\">14</span><span class=\"den\">3</span></span> + y</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">E = y - x + (<span class=\"frac\"><span class=\"num\">14</span><span class=\"den\">3</span></span> - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">8</span></span> - <span class=\"frac\"><span class=\"num\">14</span><span class=\"den\">3</span></span>)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">14</span><span class=\"den\">3</span></span> - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">8</span></span> - <span class=\"frac\"><span class=\"num\">14</span><span class=\"den\">3</span></span> = -<span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">8</span></span></span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">E = y - x - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">8</span></span></span>"}],
