    correction: [{"quoi":"نرفع القوس الأول","math":"<span dir=\"ltr\" class=\"expr\">- (<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> + x) = -<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> - x</span>"},{"quoi":"تنبيه","math":"علامة الطرح أمام قوس تنقلب على كلّ حدوده، لا على الأوّل فقط"},{"quoi":"نرفع القوس المربّع","math":"<span dir=\"ltr\" class=\"expr\">- [<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> - (x + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span>)] = -<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> + x + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span></span>"},{"quoi":"نرفع القوس الأخير","math":"<span dir=\"ltr\" class=\"expr\">+ (x - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">4</span></span>) = x - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">4</span></span></span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">A = -<span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">4</span></span> - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> - x - <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> + x + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> + x - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">4</span></span></span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">A = (-x + x + x) + (-<span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">4</span></span> - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">4</span></span>)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">4</span></span> - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">4</span></span> = -6</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">A = x - 6</span>"}],
