    correction: [{"quoi":"القاعدة","math":"إذا كان <span dir=\"ltr\" class=\"expr\">|x - <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span>| = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span></span> فإنّ <span dir=\"ltr\" class=\"expr\">x - <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span> = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span></span>  أو  <span dir=\"ltr\" class=\"expr\">x - <span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span> = -<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span></span>"},{"quoi":"الحالة الأولى","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span> + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span> = 1</span>"},{"quoi":"الحالة الثانية","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">4</span></span> - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span> = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span></span>"},{"quoi":"نعوّض في الحالة الأولى","math":"<span dir=\"ltr\" class=\"expr\">1 - 6 = -5</span>"},{"quoi":"نعوّض في الحالة الثانية","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> - 6 = -<span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">2</span></span></span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">A = -5</span>  أو  <span dir=\"ltr\" class=\"expr\">A = -<span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">2</span></span></span>"}],
