    enonce: "بيّن أنّ: <span dir=\"ltr\" class=\"expr\">A = y - x + 1</span> حيث <span dir=\"ltr\" class=\"expr\">A = -7 - (x - 10) - [8 - (y + 6)]</span>",
    correction: [{"quoi":"نرفع القوس الأول","math":"<span dir=\"ltr\" class=\"expr\">- (x - 10) = -x + 10</span>"},{"quoi":"تنبيه","math":"علامة الطرح أمام قوس تنقلب على كلّ حدوده، لا على الأوّل فقط"},{"quoi":"نرفع القوس المربّع","math":"<span dir=\"ltr\" class=\"expr\">- [8 - (y + 6)] = -8 + y + 6</span>"},{"quoi":"نكتب العبارة بدون أقواس","math":"<span dir=\"ltr\" class=\"expr\">A = -7 - x + 10 - 8 + y + 6</span>"},{"quoi":"نجمّع الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">A = y - x + (-7 + 10 - 8 + 6)</span>"},{"quoi":"نحسب الثابت","math":"<span dir=\"ltr\" class=\"expr\">-7 + 10 - 8 + 6 = 1</span>"},{"quoi":"الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">A = y - x + 1</span>"}],
